20	const defaultEventBuffer = 64
21	
22	// Runner is the subprocess-backed opencode harness. It launches opencode in
23	// run --format json mode, parses the JSON output into harness Events, and
24	// emits a final Event when the subprocess exits.
25	//
26	// opencode run auto-approves all tool permissions; no extra flags are needed
27	// for any permission level.
28	type Runner struct {
29		// Binary is the absolute path to the opencode executable. When empty the
30		// runner resolves "opencode" via PATH at Execute time.
31		Binary string
32	
33		// BaseArgs is prepended to the per-request argument list.
34		// opencode default: ["run", "--format", "json"]
35		BaseArgs []string
36	
37		// PromptMode controls how the prompt is delivered:
38		//   "arg" (default) — prompt is appended as the final positional argument
39		//   "stdin"         — prompt is piped on stdin
40		PromptMode string
41	
42		// EventBuffer overrides the per-Execute channel buffer size.
43		EventBuffer int
44	
45		// DiscoveryCache overrides model/reasoning discovery evidence in tests.
46		DiscoveryCache *harnesses.ModelDiscoveryCache
47	}
48	
49	// Info returns identity + capability metadata for this harness.
50	func (r *Runner) Info() harnesses.HarnessInfo {
51		info := harnesses.HarnessInfo{
52			Name:                 "opencode",
53			Type:                 "subprocess",
54			IsLocal:              false,
55			IsSubscription:       false,
56			ExactPinSupport:      true,
57			DefaultModel:         "opencode/gpt-5.4",
58			SupportedPermissions: []string{"safe", "supervised", "unrestricted"},
59			SupportedReasoning:   []string{"minimal", "low", "medium", "high", "max"},
60			CostClass:            "medium",
61		}
62		path := r.Binary
63		if path == "" {
64			if resolved, err := osexec.LookPath("opencode"); err == nil {
65				path = resolved
66			}
67		}
68		if path != "" {
69			info.Path = path
70			info.Available = true
71		} else {
72			info.Error = "opencode binary not found in PATH"
73		}
74		return info
75	}
