167	func (r *Runner) runStreaming(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event, seq *int64) (agg *streamAggregate, exitCode int, stderr string, runErr error, status string) {
168		base := r.BaseArgs
169		if base == nil {
170			base = []string{"run", "--format", "json"}
171		}
172		args := append([]string{}, base...)
173		modelResolution := harnesses.ResolveRunnerModelWithCache(r.DiscoveryCache, "opencode", modelcatalog.SurfaceEmbeddedOpenAI, req.Model, "opencode/gpt-5.4")
174		reasoningResolution := harnesses.ResolveRunnerReasoningWithCache(r.DiscoveryCache, "opencode", req.Reasoning)
175	
176		// opencode run auto-approves all tool permissions; no extra flags per level.
177	
178		// WorkDir flag: --dir <dir>
179		if req.WorkDir != "" {
180			args = append(args, "--dir", req.WorkDir)
181		}
182	
183		// Model flag: -m <model>
184		if modelResolution.ResolvedModel != "" {
185			args = append(args, "-m", opencodeModelArg(req.Provider, modelResolution.ResolvedModel))
186		}
187	
188		// Reasoning flag: --variant <reasoning>
189		if value := reasoningResolution.ResolvedReasoning; value != "" {
190			args = append(args, "--variant", value)
191		}
192	
193		promptMode := r.PromptMode
194		if promptMode == "" {
195			promptMode = "arg"
196		}
197		if promptMode == "arg" && req.Prompt != "" {
198			args = append(args, req.Prompt)
199		}
200	
201		runCtx, cancel := context.WithCancel(ctx)
202		defer cancel()
203	
204		cmd := harnesses.HarnessCommand(runCtx, binary, args...)
205		if req.WorkDir != "" {
206			cmd.Dir = req.WorkDir
207		}
208		if promptMode != "arg" {
209			cmd.Stdin = strings.NewReader(req.Prompt)
210		}
211		setProcessGroup(cmd)
212	
213		stdoutPipe, err := cmd.StdoutPipe()
214		if err != nil {
215			return nil, -1, "", err, "failed"
216		}
217		stderrPipe, err := cmd.StderrPipe()
218		if err != nil {
219			return nil, -1, "", err, "failed"
220		}
221	
222		if err := cmd.Start(); err != nil {
223			return nil, -1, "", err, "failed"
224		}
225		defer killProcessGroup(cmd)
226		_ = harnesses.RegisterHarnessSession(req.SessionLogDir, req.SessionID, "opencode", cmd)
227	
228		progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "opencode")
229		if progressLog != nil {
230			defer progressLog.Close()
231		}
232		if harnesses.ShouldEmitRunnerDefaultResolution(modelResolution) {
233			ev := harnesses.RunnerDefaultResolutionEvent(modelResolution, req.Metadata, seq)
234			harnesses.WriteProgressEvent(progressLog, ev)
235			select {
236			case out <- ev:
237			case <-ctx.Done():
238				return nil, -1, "", ctx.Err(), "cancelled"
239			}
240		}
241		if harnesses.ShouldEmitRunnerReasoningResolution(reasoningResolution) {
242			harnesses.LogRunnerReasoningWarning(reasoningResolution)
243			ev := harnesses.RunnerReasoningResolutionEvent(reasoningResolution, req.Metadata, seq)
244			harnesses.WriteProgressEvent(progressLog, ev)
245			select {
246			case out <- ev:
247			case <-ctx.Done():
248				return nil, -1, "", ctx.Err(), "cancelled"
249			}
250		}
251	
252		parserReader, parserWriter := io.Pipe()
253		parseDone := make(chan struct{})
254		var parseAgg *streamAggregate
255		var parseErr error
256		go func() {
257			defer close(parseDone)
258			mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
259			parseAgg, parseErr = parseOpencodeStream(runCtx, parserReader, mirrored, req.Metadata, seq)
260			close(mirrored)
261			<-mirrorDone
262		}()
263	
264		stdoutDone := make(chan struct{})
265		go func() {
266			defer close(stdoutDone)
267			_, _ = io.Copy(parserWriter, stdoutPipe)
268			_ = parserWriter.Close()
269		}()
270	
271		var stderrBuf strings.Builder
272		stderrDone := make(chan struct{})
273		go func() {
274			defer close(stderrDone)
275			_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
276		}()
277	
278		var timedOut atomic.Bool
279		if req.Timeout > 0 {
280			stop := make(chan struct{})
281			go func() {
282				select {
283				case <-stop:
284				case <-time.After(req.Timeout):
285					timedOut.Store(true)
286					cancel()
287					killProcessGroup(cmd)
288				}
289			}()
290			defer close(stop)
291		}
292	
293		// Wait for stdout to be fully read; context cancellation also wakes us up.
294		// Either way, the defer ensures process group is killed on function exit.
295		select {
296		case <-runCtx.Done():
297		case <-stdoutDone:
298		}
299	
300		<-stderrDone
301		<-parseDone
302		runErr = cmd.Wait()
303		stderr = stderrBuf.String()
304	
305		switch {
306		case timedOut.Load():
307			return parseAgg, -1, stderr, context.DeadlineExceeded, "timed_out"
308		case ctx.Err() != nil && errors.Is(ctx.Err(), context.Canceled):
309			return parseAgg, -1, stderr, ctx.Err(), "cancelled"
310		case ctx.Err() != nil && errors.Is(ctx.Err(), context.DeadlineExceeded):
311			return parseAgg, -1, stderr, ctx.Err(), "timed_out"
312		case runErr != nil:
313			ec := -1
314			var exitErr *osexec.ExitError
315			if errors.As(runErr, &exitErr) {
316				ec = exitErr.ExitCode()
317			}
318			return parseAgg, ec, stderr, runErr, "failed"
319		}
320		if parseErr != nil && !errors.Is(parseErr, context.Canceled) {
321			return parseAgg, 0, stderr, parseErr, "failed"
322		}
323		return parseAgg, 0, stderr, nil, "success"
324	}
325	
326	func opencodeModelArg(provider, model string) string {
327		provider = strings.TrimSpace(provider)
328		model = strings.TrimSpace(model)
329		if provider == "" || model == "" || strings.Contains(model, "/") {
330			return model
331		}
332		return provider + "/" + model
333	}
