335	type stringBuilderWriter struct {
336		sb *strings.Builder
337	}
338	
339	func (w *stringBuilderWriter) Write(p []byte) (int, error) {
340		return w.sb.Write(p)
341	}
342	
343	func trimErrorBlob(s string) string {
344		const max = 2048
345		s = strings.TrimSpace(s)
346		if len(s) > max {
347			return s[:max] + "...(truncated)"
348		}
349		return s
350	}
351	
352	func setProcessGroup(cmd *osexec.Cmd) {
353		if cmd.SysProcAttr == nil {
354			cmd.SysProcAttr = &syscall.SysProcAttr{}
355		}
356		setProcessGroupAttr(cmd.SysProcAttr)
357	}
