359	// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It calls
360	// the live opencode models discovery helper with a sensible timeout; on failure,
361	// returns ErrModelDiscoveryEvidenceMissing per the no-static-fallback principle.
362	func (r *Runner) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
363		binary := r.Binary
364		if binary == "" {
365			binary = "opencode"
366		}
367		snapshot, err := readOpenCodeModelDiscovery(context.Background(), binary)
368		if err != nil {
369			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery: %w", err)
370		}
371		if len(snapshot.Models) == 0 {
372			return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
373		}
374		return snapshot, nil
375	}
376	
377	// SupportedAliases returns nil: opencode requires exact provider/model
378	// identifiers and recognizes no family alias. Implements
379	// harnesses.ModelDiscoveryHarness.
380	func (r *Runner) SupportedAliases() []string {
381		return nil
382	}
383	
384	// ResolveModelAlias always returns harnesses.ErrAliasNotResolvable because
385	// opencode does not recognize family aliases. Implements
386	// harnesses.ModelDiscoveryHarness.
387	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
388		return "", harnesses.ErrAliasNotResolvable
389	}
