193	func (r *Runner) runStreaming(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event, seq *int64) (agg *streamAggregate, exitCode int, stderr string, runErr error, status string) {
194		base := r.BaseArgs
195		if base == nil {
196			base = []string{"exec", "--json"}
197		}
198		args := append([]string{}, base...)
199		modelResolution := harnesses.ResolveRunnerModelWithCache(r.DiscoveryCache, "codex", modelcatalog.SurfaceCodex, req.Model, fallbackDefaultModel)
200		reasoningResolution := harnesses.ResolveRunnerReasoningWithCache(r.DiscoveryCache, "codex", req.Reasoning)
201	
202		// Permission args: unrestricted adds --dangerously-bypass-approvals-and-sandbox
203		if req.Permissions == "unrestricted" {
204			args = append(args, "--dangerously-bypass-approvals-and-sandbox")
205		}
206	
207		// WorkDir flag: -C <dir>
208		if req.WorkDir != "" {
209			args = append(args, "-C", req.WorkDir)
210		}
211	
212		// Model flag: -m <model>
213		if modelResolution.ResolvedModel != "" {
214			args = append(args, "-m", modelResolution.ResolvedModel)
215		}
216	
217		// Reasoning flag: -c reasoning.effort=<reasoning>
218		if value := reasoningResolution.ResolvedReasoning; value != "" {
219			args = append(args, "-c", fmt.Sprintf("reasoning.effort=%s", value))
220		}
221	
222		promptMode := r.PromptMode
223		if promptMode == "" {
224			promptMode = "arg"
225		}
226		if promptMode == "arg" && req.Prompt != "" {
227			args = append(args, req.Prompt)
228		}
229	
230		runCtx, cancel := context.WithCancel(ctx)
231		defer cancel()
232	
233		cmd := harnesses.HarnessCommand(runCtx, binary, args...)
234		if req.WorkDir != "" {
235			cmd.Dir = req.WorkDir
236		}
237		if promptMode != "arg" {
238			cmd.Stdin = strings.NewReader(req.Prompt)
239		}
240		setProcessGroup(cmd)
241	
242		stdoutPipe, err := cmd.StdoutPipe()
243		if err != nil {
244			return nil, -1, "", err, "failed"
245		}
246		stderrPipe, err := cmd.StderrPipe()
247		if err != nil {
248			return nil, -1, "", err, "failed"
249		}
250	
251		if err := cmd.Start(); err != nil {
252			return nil, -1, "", err, "failed"
253		}
254		defer killProcessGroup(cmd)
255		_ = harnesses.RegisterHarnessSession(req.SessionLogDir, req.SessionID, "codex", cmd)
256	
257		progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "codex")
258		if progressLog != nil {
259			defer progressLog.Close()
260		}
261		if harnesses.ShouldEmitRunnerDefaultResolution(modelResolution) {
262			ev := harnesses.RunnerDefaultResolutionEvent(modelResolution, req.Metadata, seq)
263			harnesses.WriteProgressEvent(progressLog, ev)
264			select {
265			case out <- ev:
266			case <-ctx.Done():
267				return nil, -1, "", ctx.Err(), "cancelled"
268			}
269		}
270		if harnesses.ShouldEmitRunnerReasoningResolution(reasoningResolution) {
271			harnesses.LogRunnerReasoningWarning(reasoningResolution)
272			ev := harnesses.RunnerReasoningResolutionEvent(reasoningResolution, req.Metadata, seq)
273			harnesses.WriteProgressEvent(progressLog, ev)
274			select {
275			case out <- ev:
276			case <-ctx.Done():
277				return nil, -1, "", ctx.Err(), "cancelled"
278			}
279		}
280	
281		parserReader, parserWriter := io.Pipe()
282		parseDone := make(chan struct{})
283		var parseAgg *streamAggregate
284		var parseErr error
285		go func() {
286			defer close(parseDone)
287			mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
288			defer func() {
289				close(mirrored)
290				<-mirrorDone
291			}()
292			parseAgg, parseErr = parseCodexStream(runCtx, parserReader, mirrored, req.Metadata, seq)
293		}()
294	
295		stdoutDone := make(chan struct{})
296		go func() {
297			defer close(stdoutDone)
298			_, _ = io.Copy(parserWriter, stdoutPipe)
299			_ = parserWriter.Close()
300		}()
301	
302		var stderrBuf strings.Builder
303		stderrDone := make(chan struct{})
304		go func() {
305			defer close(stderrDone)
306			_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
307		}()
308	
309		var timedOut bool
310		if req.Timeout > 0 {
311			stop := make(chan struct{})
312			go func() {
313				select {
314				case <-stop:
315				case <-time.After(req.Timeout):
316					timedOut = true
317					cancel()
318				}
319			}()
320			defer close(stop)
321		}
322	
323		// Wait for stdout to be fully read; context cancellation also wakes us up.
324		// Either way, the defer ensures process group is killed on function exit.
325		select {
326		case <-ctx.Done():
327		case <-stdoutDone:
328		}
329	
330		<-stderrDone
331		<-parseDone
332		runErr = cmd.Wait()
333		stderr = stderrBuf.String()
334	
335		switch {
336		case timedOut:
337			return parseAgg, -1, stderr, context.DeadlineExceeded, "timed_out"
338		case ctx.Err() != nil && errors.Is(ctx.Err(), context.Canceled):
339			return parseAgg, -1, stderr, ctx.Err(), "cancelled"
340		case ctx.Err() != nil && errors.Is(ctx.Err(), context.DeadlineExceeded):
341			return parseAgg, -1, stderr, ctx.Err(), "timed_out"
342		case runErr != nil:
343			ec := -1
344			var exitErr *osexec.ExitError
345			if errors.As(runErr, &exitErr) {
346				ec = exitErr.ExitCode()
347			}
348			return parseAgg, ec, stderr, runErr, "failed"
349		}
350		if parseErr != nil && !errors.Is(parseErr, context.Canceled) {
351			return parseAgg, 0, stderr, parseErr, "failed"
352		}
353		return parseAgg, 0, stderr, nil, "success"
354	}
355	
356	type stringBuilderWriter struct {
357		sb *strings.Builder
358	}
359	
360	func (w *stringBuilderWriter) Write(p []byte) (int, error) {
361		return w.sb.Write(p)
362	}
