373	func setProcessGroup(cmd *osexec.Cmd) {
374		if cmd.SysProcAttr == nil {
375			cmd.SysProcAttr = &syscall.SysProcAttr{}
376		}
377		setProcessGroupAttr(cmd.SysProcAttr)
378	}
