173			t.Fatal(err)
174		}
175		f.Close()
176		if err := os.Chmod(f.Name(), 0o755); err != nil {
177			t.Fatal(err)
178		}
179	
180		r := &Runner{
181			Binary:   f.Name(),
182			BaseArgs: []string{},
183		}
184	
185		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
186		defer cancel()
187	
188		ch, err := r.Execute(ctx, harnesses.ExecuteRequest{
189			Prompt: "test prompt",
190		})
191		if err != nil {
192			t.Fatalf("Execute: %v", err)
193		}
194	
195		var textDeltas []string
196		var finalEv *harnesses.FinalData
197		for ev := range ch {
198			switch ev.Type {
199			case harnesses.EventTypeTextDelta:
200				var d harnesses.TextDeltaData
