210				finalEv = &fd
211			}
212		}
213	
214		if len(textDeltas) == 0 {
215			t.Error("expected at least one text_delta event")
216		} else if textDeltas[0] != "PONG" {
217			t.Errorf("unexpected text delta: %q", textDeltas[0])
218		}
219	
220		if finalEv == nil {
221			t.Fatal("no final event received")
222		}
223		if finalEv.Status != "success" {
224			t.Errorf("expected status=success, got %q (error: %s)", finalEv.Status, finalEv.Error)
225		}
226		if finalEv.FinalText != "PONG" {
227			t.Errorf("expected FinalText=%q, got %q", "PONG", finalEv.FinalText)
