30	// ModelDiscoveryCache memoizes in-process discovery snapshots by harness and
31	// source. The embedded source is populated from the registry's cassette-backed
32	// model lists; live PTY refresh is intentionally out of scope here.
33	type ModelDiscoveryCache struct {
34		mu      sync.Mutex
35		loader  ModelDiscoveryLoader
36		entries map[discoveryCacheKey]discoveryCacheEntry
37	}
38	
39	func NewModelDiscoveryCache(loader ModelDiscoveryLoader) *ModelDiscoveryCache {
40		if loader == nil {
41			loader = LoadEmbeddedModelDiscoverySnapshot
42		}
43		return &ModelDiscoveryCache{
44			loader:  loader,
45			entries: make(map[discoveryCacheKey]discoveryCacheEntry),
46		}
47	}
48	
49	func (c *ModelDiscoveryCache) Snapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
50		if c == nil {
51			c = NewModelDiscoveryCache(nil)
52		}
53		key := discoveryCacheKey{
54			harnessName: strings.TrimSpace(harnessName),
55			source:      strings.TrimSpace(source),
56		}
57		if key.source == "" {
58			key.source = EmbeddedDiscoverySource
59		}
60		c.mu.Lock()
61		if entry, ok := c.entries[key]; ok {
62			c.mu.Unlock()
63			return entry.snapshot, entry.err
64		}
65		loader := c.loader
66		c.mu.Unlock()
67	
68		snapshot, err := loader(key.harnessName, key.source)
69	
70		c.mu.Lock()
71		c.entries[key] = discoveryCacheEntry{snapshot: snapshot, err: err}
72		c.mu.Unlock()
73		return snapshot, err
74	}
