77	// HealthCheck verifies the opencode binary is present.
78	func (r *Runner) HealthCheck(ctx context.Context) error {
79		if err := ctx.Err(); err != nil {
80			return err
81		}
82		path := r.Binary
83		if path == "" {
84			resolved, err := osexec.LookPath("opencode")
85			if err != nil {
86				return fmt.Errorf("opencode binary not found: %w", err)
87			}
88			path = resolved
89		}
90		st, err := os.Stat(path)
91		if err != nil {
92			return fmt.Errorf("stat opencode binary: %w", err)
93		}
94		if st.IsDir() {
95			return fmt.Errorf("opencode binary path is a directory: %s", path)
96		}
97		return nil
98	}
