352	func setProcessGroup(cmd *osexec.Cmd) {
353		if cmd.SysProcAttr == nil {
354			cmd.SysProcAttr = &syscall.SysProcAttr{}
355		}
356		setProcessGroupAttr(cmd.SysProcAttr)
357	}
