378	func TestParseOpencodeStream_WithUsage(t *testing.T) {
379		// Simulate opencode --format json step_finish event with usage.
380		input := `{"type":"step_finish","part":{"type":"step-finish","tokens":{"total":23,"input":15,"output":8,"reasoning":0,"cache":{"write":0,"read":0}},"cost":0.003}}`
381		out := make(chan harnesses.Event, 16)
382		var seq int64
383		agg, err := parseOpencodeStream(context.Background(), strings.NewReader(input), out, nil, &seq)
384		close(out)
385		if err != nil {
386			t.Fatalf("parseOpencodeStream: %v", err)
387		}
388	
389		if len(agg.UsageSources) != 1 {
390			t.Fatalf("expected 1 usage source, got %d", len(agg.UsageSources))
391		}
392		candidate := agg.UsageSources[0]
393		if candidate.Source != harnesses.UsageSourceNativeStream {
394			t.Fatalf("expected Source=%q, got %q", harnesses.UsageSourceNativeStream, candidate.Source)
395		}
396		if candidate.Counts.InputTokens == nil || *candidate.Counts.InputTokens != 15 {
397			t.Errorf("expected InputTokens=15, got %#v", candidate.Counts.InputTokens)
398		}
399		if candidate.Counts.OutputTokens == nil || *candidate.Counts.OutputTokens != 8 {
400			t.Errorf("expected OutputTokens=8, got %#v", candidate.Counts.OutputTokens)
401		}
402		if candidate.Counts.TotalTokens == nil || *candidate.Counts.TotalTokens != 23 {
403			t.Errorf("expected TotalTokens=23, got %#v", candidate.Counts.TotalTokens)
404		}
405		if agg.CostUSD != 0.003 {
406			t.Errorf("expected CostUSD=0.003, got %f", agg.CostUSD)
407		}
408	
409		// step_finish emits no text_delta events.
410		var events []harnesses.Event
411		for ev := range out {
412			events = append(events, ev)
413		}
414		if len(events) != 0 {
415			t.Fatalf("expected 0 events, got %d", len(events))
416		}
417	}
