570	func readFinalEvent(t *testing.T, ch <-chan harnesses.Event) harnesses.FinalData {
571		t.Helper()
572		var finalEv *harnesses.FinalData
573		for ev := range ch {
574			if ev.Type != harnesses.EventTypeFinal {
575				continue
576			}
577			var fd harnesses.FinalData
578			if err := json.Unmarshal(ev.Data, &fd); err != nil {
579				t.Errorf("unmarshal final: %v", err)
580			}
581			finalEv = &fd
582		}
583		if finalEv == nil {
584			t.Fatal("no final event received")
585		}
586		return *finalEv
587	}
